svg.script:

let curShield = 'orig_clean';
let curNanite = 'pure_sph1';
let curSkin = 'default';

const shipImgs = {
  'default': 'data:image/png;base64,',
  'first_strike': 'data:image/png;base64,',
  'survivor': 'data:image/png;base64,'
};

const shieldNames = {
  'none': 'OFF',
  'curr': '★ CURRENT IN-GAME SHIELD',
  'orig_clean': 'HEX AEGIS (EXACT ORIGINAL - NO OUTER RING)',
  'orig_full': 'HEX AEGIS (ORIGINAL FULL WITH 3 NODES)'
};

const naniteNames = {
  'none': 'OFF',
  'pure_sph1': 'PURE 3D SPHERICAL PARTICLES (8 MOTES - NO GLOW)',
  'pure_sph2': 'PURE 3D CELESTIAL SWARM (12 MOTES - NO GLOW)',
  'pure_sph3': 'PURE 3D CAGE PARTICLES (6 MOTES - NO GLOW)',
  'glow_sph1': '3D SPHERE [WITH MIST GLOW]'
};

function updateDisplay() {
  // Toggle shield layers
  ['curr', 'orig_clean', 'orig_full'].forEach(id => {
    const el = document.getElementById('layer-shield-' + id);
    if (el) el.style.display = (curShield === id) ? 'block' : 'none';

    const btn = document.getElementById('btn-s-' + id);
    if (btn) {
      if (curShield === id) btn.classList.add('active');
      else btn.classList.remove('active');
    }
  });
  const btnSNone = document.getElementById('btn-s-none');
  if (btnSNone) {
    if (curShield === 'none') btnSNone.classList.add('active');
    else btnSNone.classList.remove('active');
  }

  // Toggle nanite layers
  ['pure_sph1', 'pure_sph2', 'pure_sph3', 'glow_sph1'].forEach(id => {
    const el = document.getElementById('layer-nanite-' + id);
    if (el) el.style.display = (curNanite === id) ? 'block' : 'none';

    const btn = document.getElementById('btn-n-' + id);
    if (btn) {
      if (curNanite === id) btn.classList.add('active');
      else btn.classList.remove('active');
    }
  });
  const btnNNone = document.getElementById('btn-n-none');
  if (btnNNone) {
    if (curNanite === 'none') btnNNone.classList.add('active');
    else btnNNone.classList.remove('active');
  }

  // Update active ship skin in live arena
  const arenaImg = document.getElementById('arena-ship-img');
  if (arenaImg && shipImgs[curSkin]) {
    arenaImg.setAttribute('href', shipImgs[curSkin]);
  }
  ['default', 'first_strike', 'survivor'].forEach(sk => {
    const b = document.getElementById('btn-ship-' + sk);
    if (b) {
      if (curSkin === sk) b.classList.add('active');
      else b.classList.remove('active');
    }
  });

  // Update status text
  const statusEl = document.getElementById('status-text');
  if (statusEl) {
    statusEl.textContent = 'ACTIVE COMBO: ' + shieldNames[curShield] + ' + ' + naniteNames[curNanite] + ' [' + curSkin.toUpperCase() + ' SHIP]';
  }
}

window.setShield = function(s) {
  curShield = s;
  updateDisplay();
};

window.setNanite = function(n) {
  curNanite = n;
  updateDisplay();
};

window.setShipSkin = function(sk) {
  curSkin = sk;
  updateDisplay();
};

window.applyPreset = function(s, n) {
  curShield = s;
  curNanite = n;
  updateDisplay();
};
